import re

def parsear_duracion(s: str) -> int:
    """
    Recibe un string como '1h30m', '45m' o '2h' y devuelve la cantidad total de MINUTOS como entero.
    """
    total_minutos = 0

    # Expresión regular para encontrar patrones como "Nh" o "Nm"
    # Donde N es un número y h o m es la unidad.
    matches = re.findall(r'(\d+)([hm])', s)

    for value_str, unit in matches:
        try:
            value = int(value_str)
            if unit == 'h':
                total_minutos += value * 60
            elif unit == 'm':
                total_minutos += value
        except ValueError:
            # Esto no debería ocurrir si la regex es correcta, pero es buena práctica
            pass

    return total_minutos

