def binaria(lista: list, x: int) -> int:
    """
    Busca x en una lista ordenada usando búsqueda binaria y devuelve su índice, 
    o -1 si no está.
    """
    izquierda = 0
    derecha = len(lista) - 1

    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2

        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1

    return -1

