def formatear_bytes(n):
    if n is None or n < 0:
        return "0 B"

    if n < 1024:
        return f"{int(n)} B"

    unidades = ['KB', 'MB', 'GB']
    valor = float(n)
    i = 0

    while valor >= 1024 and i < len(unidades):
        valor /= 1024
        i += 1

    if i == 0:
        # Esto solo debería pasar si n < 1024, pero como ya se manejó arriba, es un fallback
        return f"{int(n)} B"

    # Para KB, MB, GB, mostramos con un decimal
    return f"{valor:.1f} {unidades[i-1]}"

