def obtener(d, camino, defecto=None):
    """
    Busca en un dict anidado siguiendo un camino con puntos ('a.b.c') 
    y devuelve el valor, o el defecto si algún tramo no existe.

    Args:
        d (dict): El diccionario anidado a buscar.
        camino (str): La cadena que representa el camino (ej: 'a.b.c').
        defecto: El valor a retornar si el camino no existe.

    Returns:
        The value found at the specified path, or the default value.
    """
    if not isinstance(d, dict) or not isinstance(camino, str):
        return defecto

    partes = camino.split('.')

    try:
        current = d
        for parte in partes:
            if isinstance(current, dict) and parte in current:
                current = current[parte]
            else:
                return defecto
        return current
    except Exception:
