    print(f"Intermedio no dict (a.b): {obtener(datos_error, 'a.b', 'ERROR_TYPE')}")

def obtener(d, camino, defecto=None):
    """
    Busca en un dict anidado siguiendo un camino con puntos ('a.b.c') y devuelve el valor, 
    o el defecto si algún tramo no existe.
    """
    try:
        # Dividir el camino en claves
        claves = camino.split('.')

        # Iterar sobre las claves, actualizando la referencia al diccionario actual
        resultado = d
        for clave in claves:
            resultado = resultado[clave]

        return resultado
    except (KeyError, TypeError):
        # KeyError si una clave no existe en el diccionario
        # TypeError si estamos intentando acceder a una clave en algo que no es un dict (ej: None)
        return defecto

if __name__ == '__main__':
    datos = {
        "usuario": {
            "perfil": {
                "nombre": "Alice",
                "edad": 30
            },
            "contacto": {
                "email": "alice@example.com"
            }
        },
        "config": {
            "timeout": 60
        }
    }

    # Casos de éxito
    print(f"Nombre: {obtener(datos, 'usuario.perfil.nombre')}")  # Salida: Alice
    print(f"Email: {obtener(datos, 'usuario.contacto.email')}") # Salida: alice@example.com
    print(f"Timeout: {obtener(datos, 'config.timeout')}")      # Salida: 60

    # Caso de fallo: clave no existe
    print(f"Edad inexistente: {obtener(datos, 'usuario.perfil.altura', defecto='N/A')}") # Salida: N/A

    # Caso de fallo: camino incompleto
    print(f"Camino roto: {obtener(datos, 'usuario.direccion.calle', defecto='No encontrado')}") # Salida: No encontrado

    # Caso de fallo: dato intermedio no es un diccionario (maneja TypeError)
    datos_malo = {"a": 1}
    print(f"Error de tipo: {obtener(datos_malo, 'a.b', defecto='Error')}") # Salida: Error

    # Caso de fallo: camino vacío (debería devolver el defecto si se interpreta como un camino inexistente en el contexto de la búsqueda)
    # Si el camino es "", split('.') devuelve [''], lo cual fallará si el dict no tiene una clave ''
    print(f"Camino vacío: {obtener(datos, '', defecto='Vacío')}") # Salida: Vacío

    # Caso de éxito: camino de longitud 1
    print(f"Config general: {obtener(datos, 'config', defecto=None)}") # Salida: {'timeout': 60}
